familyStyles.hanken-grotesk:
@font-face {
  font-family: "Hanken Grotesk";
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("/build/assets/hanken-grotesk-100-900-normal-CaVRRdDk.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: "Hanken Grotesk fallback";
  src: local("Arial");
  ascent-override: 98.09%;
  descent-override: 29.72%;
  line-gap-override: 0.00%;
  size-adjust: 101.95%;
}

.font-hanken {
  font-family: var(--font-hanken);
}

